CREATE TABLE money_settings (id INTEGER PRIMARY KEY CHECK(id=1), start_month TEXT NOT NULL CHECK(length(start_month)=7));
CREATE TABLE money_policies (month TEXT PRIMARY KEY CHECK(length(month)=7), minimum INTEGER NOT NULL CHECK(minimum>0));
CREATE TABLE money_members (user_id INTEGER PRIMARY KEY CHECK(user_id>0), name TEXT NOT NULL, is_bot INTEGER NOT NULL CHECK(is_bot IN(0,1)));
CREATE TABLE money_memberships (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES money_members(user_id), joined TEXT NOT NULL, departed TEXT, CHECK(departed IS NULL OR departed>=joined));
CREATE UNIQUE INDEX money_active_member ON money_memberships(user_id) WHERE departed IS NULL;
CREATE TABLE money_claims (id INTEGER PRIMARY KEY, chat_id INTEGER NOT NULL, source_id INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES money_members(user_id), amount INTEGER NOT NULL CHECK(amount>0), card_id INTEGER, delivery_started INTEGER NOT NULL DEFAULT 0 CHECK(delivery_started IN(0,1)), confirmed INTEGER NOT NULL DEFAULT 0 CHECK(confirmed IN(0,1)), acknowledged INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged IN(0,1)), UNIQUE(chat_id,source_id), UNIQUE(chat_id,card_id));
CREATE TABLE money_card_attempts (chat_id INTEGER NOT NULL, source_id INTEGER NOT NULL, claim_id INTEGER NOT NULL REFERENCES money_claims(id), PRIMARY KEY(chat_id,source_id));
CREATE TABLE money_allocations (claim_id INTEGER NOT NULL REFERENCES money_claims(id), month TEXT NOT NULL CHECK(length(month)=7), amount INTEGER NOT NULL CHECK(amount>0), PRIMARY KEY(claim_id,month));
CREATE TABLE money_ledger (id INTEGER PRIMARY KEY, amount INTEGER NOT NULL CHECK(amount<>0), kind TEXT NOT NULL CHECK(kind IN('payment','income','expense','reversal')), description TEXT NOT NULL, actor INTEGER NOT NULL CHECK(actor>0), posted TEXT NOT NULL, claim_id INTEGER UNIQUE REFERENCES money_claims(id), reverse_id INTEGER UNIQUE REFERENCES money_ledger(id), chat_id INTEGER, source_id INTEGER, UNIQUE(chat_id,source_id), CHECK((kind='payment')=(claim_id IS NOT NULL)), CHECK((kind='reversal')=(reverse_id IS NOT NULL)), CHECK((kind IN('payment','income') AND amount>0) OR (kind='expense' AND amount<0) OR kind='reversal'));
